def budget_id(cat, item):
    """Stable ID that links a budget line to its row in the Bookings tab. Don't change once imported."""
    import re
    return re.sub(r"[^a-z0-9]+", "-", f"{cat} {item}".lower()).strip("-")[:48].rstrip("-")
